"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["12372"],{97552(t){t.exports=JSON.parse('{"id":"FIN-658","slug":"sustainable-growth-rate","term":"Sustainable Growth Rate","also_known_as":[],"difficulty":"Intermediate","definition":"The sustainable growth rate is the maximum rate at which a company can grow its sales and earnings using only its own retained profits, without issuing new shares or changing its level of debt relative to equity.","explanation":["A company can fund growth from retained earnings, new borrowing or new equity. The sustainable growth rate asks how fast it can grow if it relies only on the first, while keeping its financial structure unchanged.","It is commonly estimated by multiplying return on equity by the retention ratio. For example, a company with an ROE of 12% that retains 60% of its profits has a sustainable growth rate of about 7.2% a year.","The logic is that retained profits increase equity, and keeping the debt-to-equity ratio constant allows a proportional increase in borrowing. Together, these fund growth in assets and sales.","If a company wants to grow faster than its sustainable growth rate, it must change something: improve profitability, retain more profit, borrow more relative to its equity or raise new equity. Growing faster without such changes can lead to cash shortages.","The measure is a simplified planning tool. It assumes a constant ROE, dividend policy and capital structure, which may not hold in practice, but it is useful for checking whether a company\'s growth plans are financially realistic."],"note":"","total":1500,"prev":{"slug":"survivorship-bias","term":"Survivorship Bias"},"next":{"slug":"swap","term":"Swap"}}')}}]);